window.RTLBenchLSData.register("assets/d330fee5c55a780fd3ff272ae61cca75d8d6fc975b106f5ae77d369b204aeff2.txt","# JasperGold SEC: sequential equivalence (golden vs revised RTL).\n# -sv = SystemVerilog mode (accepts Verilog + SV constructs; backward compatible).\n# Placeholders replaced by verification_tools.run_sec_remote:\n#   origen_105152.v0, origen_105152.v1, origen_105152, clk, -none\n#   clk -> \"clk\" or \"clk -both_edges\" for dual-edge designs\nset DESIGN_NAME_GOLDEN \"origen_105152.v0\"\nset DESIGN_NAME \"origen_105152.v1\"\nset TOP_NAME \"origen_105152\"\n\n\nclear -all\ncheck_sec -analyze -spec -sv ./input/rtl/${DESIGN_NAME_GOLDEN}.v\ncheck_sec -analyze -imp -sv ./input/rtl/${DESIGN_NAME}.v\ncheck_sec -elaborate -spec -top ${TOP_NAME} -disable_auto_bbox\ncheck_sec -elaborate -imp -top ${TOP_NAME} -disable_auto_bbox\n# check_sec -setup clock -infer reset -none\ncheck_sec -setup \ncheck_sec -map -auto\nclock clk \nreset -none\ncheck_sec -gen\n# check_sec -prove -strategy design_style -design_style_type clock_gating\n# check_sec -prove\ncheck_sec -prove -strategy proof\n");
